// SpawnManager.cs — Object Pool con Dictionary + eventos de plataforma
using System.Collections.Generic;
using UnityEngine;

public class SpawnManager : MonoBehaviour
{
    [SerializeField] private List<GameObject> obstaclePrefabs;
    [SerializeField] private int poolSizePerType = 8;

    // Pool separado por tipo: nombre del prefab → cola de instancias
    private Dictionary<string, Queue<GameObject>> _pool;

    private void Awake()
    {
        _pool = new Dictionary<string, Queue<GameObject>>();

        // Toda la instanciación ocurre UNA SOLA VEZ al inicio
        foreach (var prefab in obstaclePrefabs)
        {
            var queue = new Queue<GameObject>(poolSizePerType);
            for (int i = 0; i < poolSizePerType; i++)
            {
                var obj = Instantiate(prefab);
                obj.SetActive(false);
                queue.Enqueue(obj);
            }
            _pool[prefab.name] = queue;
        }
    }

    // Las plataformas llaman a este método cuando lo necesitan.
    // Update ya no existe — CERO polling.
    public void RequestObstacle(Platform platform, string type)
    {
        if (!_pool.TryGetValue(type, out var queue) || queue.Count == 0)
            return;

        GameObject obs = queue.Dequeue();
        obs.transform.SetPositionAndRotation(
            platform.GetSpawnPoint(), Quaternion.identity);
        obs.SetActive(true);
        platform.RegisterObstacle(obs);
    }

    // La plataforma llama esto al desactivarse para devolver el objeto
    public void ReturnToPool(string type, GameObject obs)
    {
        obs.SetActive(false);
        if (_pool.TryGetValue(type, out var queue))
            queue.Enqueue(obs);
    }
}

