public class AuraManager : MonoBehaviour
{
    private List<Unit> _allUnits = new List<Unit>();

    public void Register(Unit u)   => _allUnits.Add(u);
    public void Unregister(Unit u) => _allUnits.Remove(u);

    // O(n²) — se ejecuta 60 veces por segundo
    private void Update()
    {
        foreach (Unit caster in _allUnits)
        {
            if (!caster.HasAura) continue;

            foreach (Unit target in _allUnits)
            {
                if (target == caster) continue;

                float dist = Vector3.Distance(
                    caster.transform.position,
                    target.transform.position
                );

                if (dist <= caster.AuraRadius)
                    target.ApplyBuff(caster.AuraType, caster.AuraPower);
                else
                    target.RemoveBuff(caster.AuraType);
            }
        }
    }
}

