// Turret.cs — cada torreta gestiona su propio rango con un SphereCollider trigger
using System.Collections.Generic;
using UnityEngine;

[RequireComponent(typeof(SphereCollider))]
public class Turret : MonoBehaviour
{
    [SerializeField] private float fireRate = 1f;
    // El radio del SphereCollider = rango de la torreta (configúralo en el Inspector)

    private float _fireCooldown;
    private Enemy _currentTarget;
    private readonly HashSet<Enemy> _enemiesInRange = new HashSet<Enemy>();

    private void Awake()
    {
        // Asegúrate de que el SphereCollider esté marcado como isTrigger en el Inspector
        GetComponent<SphereCollider>().isTrigger = true;
    }

    // Unity llama esto cuando un enemigo ENTRA al rango — no polling
    private void OnTriggerEnter(Collider other)
    {
        if (other.TryGetComponent<Enemy>(out var enemy))
        {
            _enemiesInRange.Add(enemy);
            if (_currentTarget == null) _currentTarget = enemy;
        }
    }

    // Unity llama esto cuando un enemigo SALE del rango — no polling
    private void OnTriggerExit(Collider other)
    {
        if (other.TryGetComponent<Enemy>(out var enemy))
        {
            _enemiesInRange.Remove(enemy);
            if (_currentTarget == enemy) PickNewTarget();
        }
    }

    // Solo recalcula el objetivo cuando el actual muere o sale del rango
    private void PickNewTarget()
    {
        _currentTarget = null;
        float minDist = float.MaxValue;
        foreach (Enemy e in _enemiesInRange) // SOLO los que están en rango
        {
            float d = Vector3.Distance(transform.position, e.transform.position);
            if (d < minDist) { minDist = d; _currentTarget = e; }
        }
    }

    private void Update()
    {
        // Limpieza si el enemigo fue destruido sin salir del trigger
        if (_currentTarget != null && !_currentTarget.IsAlive)
        {
            _enemiesInRange.Remove(_currentTarget);
            PickNewTarget();
        }
        if (_currentTarget == null) return;

        transform.LookAt(_currentTarget.transform);
        _fireCooldown -= Time.deltaTime;
        if (_fireCooldown <= 0f)
        {
            Shoot(_currentTarget);
            _fireCooldown = 1f / fireRate;
        }
    }

    private void Shoot(Enemy target) { /* lanzar proyectil desde pool */ }

    // TurretManager central ya no necesita Update — se puede eliminar
}

