{
    public static ProjectileManager Instance;
    public List<Projectile> ActiveProjectiles = new List<Projectile>();
    public List<Enemy>      ActiveEnemies     = new List<Enemy>();

    private void Awake() => Instance = this;

    // O(balas × enemigos) — hot path principal del juego
    private void Update()
    {
        for (int i = ActiveProjectiles.Count - 1; i >= 0; i--)
        {
            Projectile p = ActiveProjectiles[i];
            if (!p.gameObject.activeSelf) continue;

            for (int j = ActiveEnemies.Count - 1; j >= 0; j--)
            {
                Enemy e = ActiveEnemies[j];
                float dist = Vector3.Distance(
                    p.transform.position,
                    e.transform.position
                );

                if (dist < p.HitRadius + e.ColliderRadius)
                {
                    e.TakeDamage(p.Damage);
                    ActiveProjectiles.RemoveAt(i);
                    Destroy(p.gameObject);
                    break;
                }
            }
        }
    }
}

