// Projectile.cs — colisión delegada al motor, pool para evitar GC
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D), typeof(CircleCollider2D))]
public class Projectile : MonoBehaviour
{
    public float Damage { get; private set; }
    public float Speed  { get; private set; }

    private Rigidbody2D _rb;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _rb.gravityScale = 0f;
        // CircleCollider2D: isTrigger = true (configúralo en el Inspector)
        // Layer del GameObject: "Projectile"
        // En Edit > Project Settings > Physics 2D > Layer Collision Matrix:
        //   "Projectile" solo interactúa con "Enemy" — el resto ignorado
    }

    // El pool llama esto en lugar de Instantiate en runtime
    public void Launch(Vector2 direction, float damage, float speed)
    {
        Damage = damage;
        Speed  = speed;
        _rb.linearVelocity = direction.normalized * speed;
    }

    // Unity invoca esto SOLO cuando toca un objeto en layer "Enemy"
    // CERO loops manuales — el motor de físicas hace broadphase + narrowphase
    private void OnTriggerEnter2D(Collider2D other)
    {
        if (other.TryGetComponent<Enemy>(out var enemy))
            enemy.TakeDamage(Damage);

        ReturnToPool();
    }

    private void ReturnToPool()
    {
        _rb.linearVelocity = Vector2.zero;
        gameObject.SetActive(false); // el ProjectilePool lo recoge
    }
}

// ProjectilePool.cs — gestiona el ciclo de vida sin Instantiate/Destroy
public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private Projectile prefab;
    [SerializeField] private int initialSize = 80;
    private Queue<Projectile> _available = new Queue<Projectile>();

    private void Awake()
    {
        for (int i = 0; i < initialSize; i++)
        {
            var p = Instantiate(prefab);
            p.gameObject.SetActive(false);
            _available.Enqueue(p);
        }
    }

    public Projectile Get(Vector2 pos, Vector2 dir, float dmg, float spd)
    {
        var p = _available.Count > 0 ? _available.Dequeue() : Instantiate(prefab);
        p.transform.position = pos;
        p.gameObject.SetActive(true);
        p.Launch(dir, dmg, spd);
        return p;
    }

    public void Return(Projectile p) => _available.Enqueue(p);
}

