using System.Collections.Generic;
using UnityEngine;

public class TileGrid : MonoBehaviour
{
    // Clave: posición en la grilla — Valor: Tile en esa posición
    // Lookup O(1) en lugar de O(n)
    private Dictionary<Vector2Int, Tile> _tileMap =
        new Dictionary<Vector2Int, Tile>();

    public void AddTile(Tile tile)
    {
        _tileMap[tile.GridPosition] = tile;
    }

    // O(1) — acceso directo por clave
    public Tile GetTileAt(Vector2Int pos)
    {
        _tileMap.TryGetValue(pos, out Tile tile);
        return tile; // null si no existe
    }

    private void Update()
    {
        Vector2Int selected = GetSelectedPosition();

        // Cada GetTileAt es ahora O(1) — sin recorrer nada
        Tile current = GetTileAt(selected);
        Tile above   = GetTileAt(selected + Vector2Int.up);
        Tile below   = GetTileAt(selected + Vector2Int.down);
        Tile right   = GetTileAt(selected + Vector2Int.right);
        Tile left    = GetTileAt(selected + Vector2Int.left);

        ValidateSwap(current, above, below, right, left);
    }

    // Para mover un tile: actualizar la clave en el Dictionary
    public void MoveTile(Tile tile, Vector2Int newPos)
    {
        _tileMap.Remove(tile.GridPosition);
        tile.GridPosition = newPos;
        _tileMap[newPos] = tile;
    }

