// PropManager.cs — dos estrategias para reducir draw calls
using UnityEngine;

public class PropManager : MonoBehaviour
{
    // ── ESTRATEGIA A: Static Batching ─────────────────────────────────────────
    // Para props que NUNCA se mueven. Unity combina sus meshes en un solo buffer
    // en tiempo de build/carga → 200 objetos = 1-2 draw calls.
    //
    // Opción 1: marcar como Static en el Inspector ("Static" checkbox).
    // Opción 2: hacerlo en código:
    [SerializeField] private GameObject[] staticPropPrefabs;
    [SerializeField] private Transform[]  spawnPoints;

    private void Start()
    {
        GameObject[] instances = new GameObject[spawnPoints.Length];
        for (int i = 0; i < spawnPoints.Length; i++)
        {
            instances[i] = Instantiate(
                staticPropPrefabs[i % staticPropPrefabs.Length],
                spawnPoints[i].position,
                spawnPoints[i].rotation
            );
            // Marcar como Static en runtime para que Unity los agrupe
            instances[i].isStatic = true;
        }
        // Combinar todos los meshes estáticos en un solo draw call
        StaticBatchingUtility.Combine(instances, gameObject);
    }
}

// ── ESTRATEGIA B: GPU Instancing con DrawMeshInstanced ────────────────────────
// Para props con el mismo mesh+material. La GPU dibuja todas las instancias
// en UN SOLO draw call usando una matriz de transformaciones.
// Requiere que el material tenga "Enable GPU Instancing" activado.
using UnityEngine;

public class PropInstancer : MonoBehaviour
{
    [SerializeField] private Mesh     propMesh;
    [SerializeField] private Material propMaterial; // debe tener enableInstancing = true
    [SerializeField] private Transform[] spawnPoints;

    private Matrix4x4[] _matrices;

    private void Awake()
    {
        // Precalcular las matrices de transformación — sin crear GameObjects
        _matrices = new Matrix4x4[spawnPoints.Length];
        for (int i = 0; i < spawnPoints.Length; i++)
        {
            _matrices[i] = Matrix4x4.TRS(
                spawnPoints[i].position,
                spawnPoints[i].rotation,
                Vector3.one
            );
        }
        // Activar GPU Instancing en el material
        propMaterial.enableInstancing = true;
    }

    private void Update()
    {
        // 1 draw call para TODAS las instancias — la GPU las procesa en paralelo
        Graphics.DrawMeshInstanced(propMesh, 0, propMaterial, _matrices);
    }
}

