// WaveSpawner.cs — Coroutine: cero overhead entre spawns
using System.Collections;
using UnityEngine;

public class WaveSpawner : MonoBehaviour
{
    [SerializeField] private GameObject enemyPrefab;
    [SerializeField] private Transform[] spawnPoints;
    [SerializeField] private float spawnInterval  = 5f;
    [SerializeField] private int   enemiesPerWave = 10;

    private void Start()
    {
        // Iniciar el bucle de spawn — Update ya NO existe
        StartCoroutine(SpawnLoop());
    }

    // IEnumerator: se ejecuta solo cuando WaitForSeconds termina
    // Entre spawns el hilo principal no toca este código
    private IEnumerator SpawnLoop()
    {
        while (true)
        {
            yield return new WaitForSeconds(spawnInterval); // suspende aquí
            SpawnWave(); // solo se ejecuta cuando el tiempo llegó
        }
    }

    private void SpawnWave()
    {
        for (int i = 0; i < enemiesPerWave; i++)
        {
            Transform sp = spawnPoints[i % spawnPoints.Length];
            Instantiate(enemyPrefab, sp.position, sp.rotation);
        }
    }

    // Alternativa más simple con InvokeRepeating (sin Coroutine):
    // private void Start() =>
    //     InvokeRepeating(nameof(SpawnWave), spawnInterval, spawnInterval);
}

