// CombatLog.cs — StringBuilder: cero allocations por mensaje
using System.Collections.Generic;
using System.Text;
using UnityEngine;
using UnityEngine.UI;

public class CombatLog : MonoBehaviour
{
    [SerializeField] private Text logText;
    [SerializeField] private int  maxMessages = 20;

    // StringBuilder reutilizable — el buffer interno crece pero no se recrea
    private readonly StringBuilder _sb = new StringBuilder(2048);

    // Queue para mantener solo las últimas N líneas
    private readonly Queue<string> _messages = new Queue<string>();

    // Llamado 10-20 veces por segundo — sin allocations de string aquí
    public void AddMessage(string message)
    {
        _messages.Enqueue(message);

        // Limitar a maxMessages líneas — Dequeue libera la referencia más antigua
        if (_messages.Count > maxMessages)
            _messages.Dequeue();

        RefreshUI();
    }

    // Reconstruye el StringBuilder solo cuando hay un cambio
    private void RefreshUI()
    {
        _sb.Clear(); // limpia sin new allocation

        foreach (string msg in _messages)
            _sb.AppendLine(msg); // Append: O(longitud del mensaje), no O(total)

        // ToString() crea UN string para la UI — una sola allocation por refresh
        logText.text = _sb.ToString();
    }

    public void ClearLog()
    {
        _messages.Clear();
        _sb.Clear();
        logText.text = string.Empty;
    }
}
